(() => {
  'use strict';
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const $ = (id) => document.getElementById(id);
  const keys = new Set();
  const trackLength = 5793, lapsTotal = 3, segment = 45, viewDistance = 2700;
  const ratios = [0, 3.15, 2.45, 1.94, 1.60, 1.36, 1.18, 1.04, .94];
  let W = 0, H = 0, DPR = 1, started = false, paused = false, last = 0, raceTime = 0;
  let car, opponents, audio = null, soundOn = false, messageTimeout = 0;
  let trees = [], clouds = [];
  const clamp = (n, a, b) => Math.max(a, Math.min(b, n));
  const lerp = (a, b, t) => a + (b - a) * t;
  const fmtTime = (n) => { const m = Math.floor(n / 60), s = Math.floor(n % 60), ms = Math.floor((n % 1) * 1000); return `${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}.${String(ms).padStart(3,'0')}`; };
  const modulo = (n, m) => ((n % m) + m) % m;
  function resize() { DPR = Math.min(window.devicePixelRatio || 1, 1.7); W = innerWidth; H = innerHeight; canvas.width = Math.round(W * DPR); canvas.height = Math.round(H * DPR); ctx.setTransform(DPR, 0, 0, DPR, 0, 0); }
  function setup() {
    car = { speed: 0, gear: 1, rpm: 4200, lateral: 0, steer: 0, progress: 0, lap: 1, grip: 1, wear: 0, temp: 88, ers: 1, shiftCut: 0, shiftFlash: 0, offTrack: false, throttle: 0, brake: 0, slip: 0, lapStart: 0 };
    opponents = Array.from({length: 7}, (_, i) => ({ name: ['NOVA','KAI','MILO','LEO','AXEL','IVAN','THEO'][i], color: ['#ff4d41','#54c8ff','#f4bd46','#b25fff','#45e1a3','#ff7daa','#e6e9ef'][i], progress: trackLength * (1 - (i + 1) / 8) - (i * 13), speed: 50 + (i % 3) * 1.5, lateral: (i % 2 ? .27 : -.27), phase: i * 1.7 }));
    trees = Array.from({length: 100}, (_, i) => ({ d: i * 113, side: i % 2 ? 1 : -1, kind: i % 4, scale: .65 + Math.random() * .8 }));
    clouds = Array.from({length: 9}, (_, i) => ({ x: i / 9, y: .12 + Math.random() * .22, s: .5 + Math.random() * .8 }));
    buildRPM();
  }
  function buildRPM() { $('rpmBars').innerHTML = Array.from({length: 18}, (_, i) => `<i data-i="${i}"></i>`).join(''); }
  function curveAt(distance) {
    const p = modulo(distance, trackLength) / trackLength;
    return .00034 * Math.sin(p * Math.PI * 2 * 2.15 + .35) + .00052 * Math.sin(p * Math.PI * 2 * 4.7 - .8) + .00033 * Math.sin(p * Math.PI * 2 * 8.3 + 1.2) + .0008 * Math.exp(-Math.pow((p - .20) / .025, 2)) - .0010 * Math.exp(-Math.pow((p - .53) / .035, 2));
  }
  function getCorner(p) {
    const names = [[.025,'CURVA GRANDE'],[.115,'VARIANTE DEL RETTIFILO'],[.20,'CURVA GRANDE'],[.34,'LESmo 1'],[.40,'LESmo 2'],[.52,'ASCARI'],[.69,'PARABOLICA'],[.87,'START / FINISH']];
    let best = names[0], diff = 1;
    for (const n of names) { const d = Math.abs(p - n[0]); if (d < diff) { diff = d; best = n; } }
    return diff < .045 ? best[1] : 'MONZA · CIRCUIT';
  }
  function sky() {
    const g = ctx.createLinearGradient(0, 0, 0, H * .64); g.addColorStop(0, '#4d8ca9'); g.addColorStop(.52, '#a7c7c5'); g.addColorStop(1, '#e0cfac'); ctx.fillStyle = g; ctx.fillRect(0, 0, W, H);
    const sun = ctx.createRadialGradient(W * .78, H * .18, 5, W * .78, H * .18, H * .24); sun.addColorStop(0, 'rgba(255,244,198,.65)'); sun.addColorStop(1, 'rgba(255,235,180,0)'); ctx.fillStyle = sun; ctx.fillRect(W * .5, 0, W * .5, H * .48);
    for (const c of clouds) { const x = modulo(c.x * W + raceTime * 2.6, W + 220) - 100, y = c.y * H; ctx.fillStyle = 'rgba(246,246,236,.17)'; ctx.beginPath(); ctx.ellipse(x, y, 65 * c.s, 12 * c.s, -.05, 0, Math.PI * 2); ctx.ellipse(x + 27 * c.s, y - 3 * c.s, 35 * c.s, 15 * c.s, 0, 0, Math.PI * 2); ctx.fill(); }
    const hz = H * .39; ctx.fillStyle = '#596b4d'; ctx.beginPath(); ctx.moveTo(0, hz + 20); for (let x = 0; x <= W; x += 35) ctx.lineTo(x, hz - 8 - Math.sin(x * .008) * 15 - Math.sin(x * .021) * 8); ctx.lineTo(W, hz + 45); ctx.closePath(); ctx.fill();
    // distant grandstand and forest silhouettes
    ctx.fillStyle = '#293c31'; for (let x = -10; x < W; x += 19) { const y = hz + 4 + Math.sin(x * .13) * 4, h = 18 + Math.abs(Math.sin(x * .31)) * 27; ctx.beginPath(); ctx.moveTo(x - 11, y + 20); ctx.lineTo(x, y - h); ctx.lineTo(x + 12, y + 20); ctx.fill(); }
    ctx.fillStyle = '#657975'; ctx.fillRect(0, hz + 20, W, H - hz - 20);
    // pit buildings / grandstands on the left horizon
    ctx.fillStyle = '#c9c4b5'; ctx.fillRect(W * .04, hz - 1, W * .19, 30); ctx.fillStyle = '#8d3032'; ctx.fillRect(W * .04, hz - 5, W * .19, 7);
    ctx.fillStyle = 'rgba(255,255,255,.55)'; for (let x = W * .055; x < W * .22; x += 12) ctx.fillRect(x, hz + 5, 7, 7);
  }
  function projection(d) { const t = clamp(1 - d / viewDistance, 0, 1); return { y: H * .39 + (H * .96 - H * .39) * Math.pow(t, 1.56), t, width: (W * .43) * (t * .91 + .045) }; }
  function drawTrack() {
    sky();
    const count = Math.ceil(viewDistance / segment), points = [{d:0,dx:0}]; let dx = 0;
    for (let i = 1; i <= count; i++) { const d = i * segment; dx += curveAt(car.progress + d) * segment * d * .00020; points.push({d,dx}); }
    for (let i = count - 1; i >= 0; i--) {
      const a = points[i], b = points[i + 1], pa = projection(a.d), pb = projection(b.d);
      const bendA = a.dx * (pa.t * 1.0), bendB = b.dx * (pb.t * 1.0), cxA = W / 2 + bendA, cxB = W / 2 + bendB;
      const wA = pa.width, wB = pb.width;
      const stripe = Math.floor((car.progress + a.d) / (segment * 2)) % 2;
      ctx.fillStyle = stripe ? '#698654' : '#748e5a'; ctx.fillRect(0, pb.y, W, pa.y - pb.y + 1);
      // runoff and red-white kerbs
      ctx.fillStyle = stripe ? '#e5e3d8' : '#d84137'; ctx.beginPath(); ctx.moveTo(cxB - wB * 1.12, pb.y); ctx.lineTo(cxB - wB, pb.y); ctx.lineTo(cxA - wA, pa.y); ctx.lineTo(cxA - wA * 1.12, pa.y); ctx.closePath(); ctx.fill();
      ctx.beginPath(); ctx.moveTo(cxB + wB, pb.y); ctx.lineTo(cxB + wB * 1.12, pb.y); ctx.lineTo(cxA + wA * 1.12, pa.y); ctx.lineTo(cxA + wA, pa.y); ctx.closePath(); ctx.fill();
      ctx.fillStyle = stripe ? '#ece8da' : '#d8322f';
      ctx.beginPath(); ctx.moveTo(cxB - wB, pb.y); ctx.lineTo(cxB - wB * .955, pb.y); ctx.lineTo(cxA - wA * .955, pa.y); ctx.lineTo(cxA - wA, pa.y); ctx.closePath(); ctx.fill();
      ctx.beginPath(); ctx.moveTo(cxB + wB * .955, pb.y); ctx.lineTo(cxB + wB, pb.y); ctx.lineTo(cxA + wA, pa.y); ctx.lineTo(cxA + wA * .955, pa.y); ctx.closePath(); ctx.fill();
      ctx.fillStyle = '#3e4343'; ctx.beginPath(); ctx.moveTo(cxB - wB * .955, pb.y); ctx.lineTo(cxB + wB * .955, pb.y); ctx.lineTo(cxA + wA * .955, pa.y); ctx.lineTo(cxA - wA * .955, pa.y); ctx.closePath(); ctx.fill();
      // asphalt racing line / seam
      ctx.strokeStyle = 'rgba(225,227,219,.07)'; ctx.lineWidth = Math.max(.5, pa.t * 1.2); ctx.beginPath(); ctx.moveTo(cxB, pb.y); ctx.lineTo(cxA, pa.y); ctx.stroke();
      // track-side advertising boards and barriers
      if (i % 3 === 0 && pa.t > .04) {
        const h = Math.max(2, 22 * pa.t), boardW = Math.max(5, 56 * pa.t);
        for (const side of [-1, 1]) { const bx = cxA + side * wA * 1.27; ctx.fillStyle = '#d6d4ca'; ctx.fillRect(bx - boardW / 2, pa.y - h, boardW, h); ctx.fillStyle = '#bd1f2e'; ctx.fillRect(bx - boardW / 2, pa.y - h, boardW, h * .22); ctx.fillStyle = 'rgba(30,40,43,.75)'; ctx.font = `bold ${Math.max(3, 7 * pa.t)}px sans-serif`; ctx.textAlign = 'center'; ctx.fillText('APEX', bx, pa.y - h * .32); }
      }
    }
    drawTrees(points);
    drawStartLine(points);
    drawRivals(points);
    drawCar();
    drawSpeedLines();
  }
  function drawTrees(points) {
    for (const tree of trees) {
      let d = modulo(tree.d - car.progress, trackLength); if (d > viewDistance) continue;
      const p = projection(d), idx = Math.min(points.length - 1, Math.floor(d / segment)), center = W / 2 + points[idx].dx * p.t;
      const x = center + tree.side * (p.width * 1.28 + 20 * p.t), size = Math.max(2, p.t * (54 * tree.scale));
      ctx.fillStyle = '#384133'; ctx.fillRect(x - size * .09, p.y - size * .34, size * .18, size * .34);
      ctx.fillStyle = tree.kind === 0 ? '#244b36' : tree.kind === 1 ? '#365a3e' : '#2c5036';
      ctx.beginPath(); ctx.moveTo(x - size * .52, p.y - size * .23); ctx.lineTo(x, p.y - size * 1.4); ctx.lineTo(x + size * .52, p.y - size * .23); ctx.fill();
      ctx.fillStyle = 'rgba(171,195,121,.15)'; ctx.beginPath(); ctx.moveTo(x - size * .22, p.y - size * .48); ctx.lineTo(x, p.y - size * 1.32); ctx.lineTo(x + size * .06, p.y - size * .46); ctx.fill();
    }
  }
  function drawStartLine(points) {
    const d = modulo(-car.progress, trackLength); if (d > viewDistance || d < segment) return;
    const idx = Math.min(points.length - 1, Math.floor(d / segment)), p = projection(d), c = W / 2 + points[idx].dx * p.t, w = p.width * .95;
    const rows = 4, cols = 16, cell = w * 2 / cols, rh = Math.max(2, 8 * p.t);
    for (let r = 0; r < rows; r++) for (let col = 0; col < cols; col++) { ctx.fillStyle = (r + col) % 2 ? '#f5f4ed' : '#17191b'; ctx.fillRect(c - w + col * cell, p.y - r * rh, cell + .5, rh + .3); }
  }
  function drawRivals(points) {
    for (const rival of opponents) {
      let d = modulo(rival.progress - car.progress, trackLength); if (d > viewDistance || d < 22) continue;
      const p = projection(d), idx = Math.min(points.length - 1, Math.floor(d / segment)), center = W / 2 + points[idx].dx * p.t;
      const x = center + rival.lateral * p.width * 1.55, y = p.y - p.t * 10, s = Math.max(.15, p.t * .72);
      drawF1(x, y, s, rival.color, false);
    }
  }
  function rounded(x,y,w,h,r,fill){ctx.fillStyle=fill;ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill();}
  function drawF1(x, y, s, color, player) {
    ctx.save(); ctx.translate(x,y); ctx.scale(s,s);
    ctx.shadowColor='rgba(0,0,0,.4)';ctx.shadowBlur=14;ctx.shadowOffsetY=8;
    // slick tyres
    rounded(-39,-38,15,37,5,'#111315'); rounded(24,-38,15,37,5,'#111315'); rounded(-34,10,14,34,5,'#101214'); rounded(20,10,14,34,5,'#101214');
    ctx.shadowBlur=0;ctx.shadowOffsetY=0;
    for (const [tx,ty] of [[-32,-30],[31,-30],[-27,17],[27,17]]) { ctx.fillStyle='rgba(255,255,255,.12)';ctx.fillRect(tx,ty,2,24); }
    // rear wing
    ctx.fillStyle='#15191d';ctx.beginPath();ctx.moveTo(-44,27);ctx.lineTo(-38,18);ctx.lineTo(39,18);ctx.lineTo(45,27);ctx.lineTo(41,32);ctx.lineTo(-41,32);ctx.closePath();ctx.fill();
    ctx.fillStyle=color;ctx.beginPath();ctx.moveTo(-23,27);ctx.lineTo(-19,13);ctx.lineTo(-14,-16);ctx.lineTo(-8,-33);ctx.lineTo(0,-39);ctx.lineTo(8,-33);ctx.lineTo(14,-16);ctx.lineTo(19,13);ctx.lineTo(23,27);ctx.closePath();ctx.fill();
    // sidepods
    ctx.fillStyle=color;ctx.beginPath();ctx.moveTo(-17,-2);ctx.lineTo(-32,0);ctx.lineTo(-29,13);ctx.lineTo(-17,17);ctx.fill();ctx.beginPath();ctx.moveTo(17,-2);ctx.lineTo(32,0);ctx.lineTo(29,13);ctx.lineTo(17,17);ctx.fill();
    ctx.fillStyle='rgba(255,255,255,.2)';ctx.beginPath();ctx.moveTo(-5,-33);ctx.lineTo(0,-37);ctx.lineTo(4,-27);ctx.lineTo(0,10);ctx.fill();
    // cockpit halo and helmet
    ctx.fillStyle='#090d10';ctx.beginPath();ctx.ellipse(0,-10,8,12,0,0,Math.PI*2);ctx.fill();
    ctx.fillStyle=player?'#d8ff3e':'#f3d16b';ctx.beginPath();ctx.ellipse(0,-12,5,7,0,0,Math.PI*2);ctx.fill();
    ctx.strokeStyle='#c9d0ce';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-11,-17);ctx.quadraticCurveTo(-10,-25,0,-24);ctx.quadraticCurveTo(10,-25,11,-17);ctx.stroke();
    // front wing
    ctx.fillStyle='#14191d';ctx.beginPath();ctx.moveTo(-43,-32);ctx.lineTo(-39,-37);ctx.lineTo(-11,-35);ctx.lineTo(0,-32);ctx.lineTo(11,-35);ctx.lineTo(39,-37);ctx.lineTo(43,-32);ctx.lineTo(37,-28);ctx.lineTo(10,-29);ctx.lineTo(0,-27);ctx.lineTo(-10,-29);ctx.lineTo(-37,-28);ctx.closePath();ctx.fill();
    ctx.fillStyle=color;ctx.fillRect(-39,-36,10,3);ctx.fillRect(29,-36,10,3);
    ctx.fillStyle='rgba(255,255,255,.8)';ctx.fillRect(-2,3,4,8);ctx.fillStyle='#ff4137';ctx.fillRect(-2,24,4,3);
    ctx.restore();
  }
  function drawCar() {
    const x = W * .5 + car.lateral * W * .19, y = H * .83;
    // subtle shadow + speed glow
    const grd = ctx.createRadialGradient(x,y+20,8,x,y+20,95); grd.addColorStop(0,'rgba(0,0,0,.55)');grd.addColorStop(1,'rgba(0,0,0,0)');ctx.fillStyle=grd;ctx.fillRect(x-100,y-10,200,120);
    ctx.save(); if (Math.abs(car.steer)>.3) {ctx.translate(x,y);ctx.rotate(-car.steer*.035);ctx.translate(-x,-y);} drawF1(x,y,1.05,'#e92032',true); ctx.restore();
  }
  function drawSpeedLines() {
    if (car.speed < 53) return; const alpha = clamp((car.speed-53)/70,0,.15); ctx.strokeStyle=`rgba(235,245,250,${alpha})`;ctx.lineWidth=1;
    for(let i=0;i<8;i++){const y=H*(.48+(i*37%43)/100), side=i%2?1:-1, x=side<0?W*.08+i*13:W*.92-i*13;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+side*12,y+27);ctx.stroke();}
  }
  function input(k) { return keys.has(k) || (k==='w' && keys.has('arrowup')) || (k==='s' && keys.has('arrowdown')) || (k==='a' && keys.has('arrowleft')) || (k==='d' && keys.has('arrowright')); }
  function shift(dir) {
    if(!started||paused) return; const next=clamp(car.gear+dir,1,8); if(next===car.gear)return;
    const old=car.gear;car.gear=next;car.shiftCut=.13;car.shiftFlash=.35;
    // shift blip / mechanical click
    if(soundOn) beep(next>old?540:330,.035,'square',.025);
    showMessage(next>old?'UPSHIFT  ↑':'DOWNSHIFT  ↓',550);
  }
  function update(dt) {
    if(!started||paused)return;
    dt=Math.min(dt,.04);raceTime+=dt;
    const throttle=input('w')?1:0, brake=input('s')?1:0, steer=(input('d')?1:0)-(input('a')?1:0), boost=keys.has(' ');
    car.throttle=throttle;car.brake=brake;car.steer=lerp(car.steer,steer,1-Math.exp(-dt*7));
    const ratio=ratios[car.gear], wheel=car.speed/.33*ratio*3.25*60/(Math.PI*2), rawRPM=car.gear===1&&car.speed<1?4200:wheel;
    car.rpm=clamp(lerp(car.rpm,rawRPM,1-Math.exp(-dt*8)),3800,13700);
    const rpmNorm=clamp((car.rpm-4000)/9000,0,1), torque=1-.36*Math.pow((rpmNorm-.58)/.58,2);
    const ersFactor=boost&&car.ers>.01?1.22:1; if(boost&&car.ers>0)car.ers=Math.max(0,car.ers-dt*.17);else car.ers=Math.min(1,car.ers+dt*.042);
    const aero=.0045*car.speed*car.speed, rolling=120+car.speed*4.4, engine=throttle?(9200*torque*ersFactor*(car.shiftCut>0?.08:1)):0;
    const brakeForce=brake?Math.min(car.speed*2200,brake*15600):0, off= Math.abs(car.lateral)>1 ? 1 : 0;
    const grip=clamp(1-car.wear*.56-Math.max(0,Math.abs(car.temp-94)-22)*.003, .42,1);car.grip=grip;
    car.speed=Math.max(0,car.speed+(engine-brakeForce-aero-rolling*(1+off*2))/820*dt);
    if(car.speed>93)car.speed=lerp(car.speed,93,dt*.35);
    car.shiftCut=Math.max(0,car.shiftCut-dt);car.shiftFlash=Math.max(0,car.shiftFlash-dt);
    // Steering load, slip angle, grip loss and tyre wear are integrated with speed.
    const speedFactor=clamp(car.speed/22,0,1.5), lateralAccel=Math.abs(car.steer)*speedFactor*1.35;
    car.slip=clamp(lateralAccel/(grip*1.2)-.7,0,1.8);
    const lateralResponse=car.steer*speedFactor*.36*grip*(1-car.slip*.56);
    car.lateral += (lateralResponse - car.lateral*clamp(car.speed*.006,0,.4))*dt;
    car.lateral=clamp(car.lateral,-1.45,1.45);
    car.offTrack=Math.abs(car.lateral)>.88;
    car.wear=clamp(car.wear+dt*(.000018+car.slip*.00012+(car.offTrack?.00025:0)),0,.58);
    car.temp=lerp(car.temp, 86+throttle*19+brake*17+car.slip*24-(car.speed<25?8:0),dt*.06);
    if(car.offTrack){car.speed=Math.max(0,car.speed-dt*(4+car.speed*.13));car.grip*=.68;}
    car.progress+=car.speed*dt;
    if(car.progress>=trackLength){car.progress-=trackLength;car.lap++;if(car.lap>lapsTotal){car.lap=lapsTotal;finishRace();}else showMessage(`LAP ${String(car.lap).padStart(2,'0')}`,1700);}
    for(const o of opponents){o.progress+=o.speed*dt + Math.sin(raceTime*.24+o.phase)*.18;if(o.progress>=trackLength*3)o.progress=trackLength*3;}
    if(Math.abs(car.lateral)>1.30){car.lateral=Math.sign(car.lateral)*1.3;car.speed*=.992;}
    if(soundOn) updateEngineSound();
    updateHUD();
  }
  function updateHUD(){
    $('speed').textContent=String(Math.round(car.speed*3.6)).padStart(3,'0');$('gear').textContent=String(car.gear);$('rpmText').textContent=Math.round(car.rpm).toLocaleString('en-US');
    const ratio=clamp((car.rpm-4000)/9500,0,1);document.querySelectorAll('.rpm-bars i').forEach((el,i)=>{el.className=i<ratio*18?(i>14?'hot':'on'):'';});
    $('throttleMeter').style.width=`${car.throttle*100}%`;$('brakeMeter').style.width=`${car.brake*100}%`;$('throttleText').textContent=`${Math.round(car.throttle*100)}%`;$('brakeText').textContent=`${Math.round(car.brake*100)}%`;
    $('gripText').textContent=`${Math.round(car.grip*100)}%`;for(const id of ['tyreFL','tyreFR','tyreRL','tyreRR']){const el=$(id);el.style.opacity=String(.4+car.grip*.6);el.style.borderColor=car.grip<.7?'#ff6656':'#aaff42';}
    $('ersMeter').style.width=`${car.ers*100}%`;$('ersText').textContent=`${Math.round(car.ers*100)}%`;$('lap').textContent=String(Math.min(car.lap,lapsTotal)).padStart(2,'0');$('timer').textContent=fmtTime(raceTime);
    $('cornerName').textContent=getCorner(car.progress/trackLength);
    const rank=1+opponents.filter(o=>o.progress>raceTime*0+car.progress+(car.lap-1)*trackLength).length;
    $('position').textContent=`P ${String(clamp(rank,1,8)).padStart(2,'0')}`;
    $('statusText').textContent=car.offTrack?'OFF TRACK · GRIP LIMITED':car.slip>.7?'TYRE SLIP · EASE OFF':'RACE IN PROGRESS';
    $('drsState').innerHTML=`DRS <b>${car.speed>45?'ACTIVE':'READY'}</b>`;
    if(car.offTrack){$('statusText').style.color='#ff7868';}else $('statusText').style.color='';
  }
  function showMessage(text,ms=900){$('messageText').textContent=text;$('raceMessage').classList.add('show');clearTimeout(messageTimeout);messageTimeout=setTimeout(()=>$('raceMessage').classList.remove('show'),ms);}
  function begin(){if(started)return;started=true;paused=false;car.gear=1;raceTime=0;last=performance.now();$('startCard').classList.add('hidden');$('raceMessage').classList.add('show');$('messageText').textContent='LIGHTS OUT';setTimeout(()=>$('raceMessage').classList.remove('show'),1500);$('mobileControls').style.display='';}
  function finishRace(){paused=true;showMessage('CHEQUERED FLAG',5000);$('statusText').textContent='RACE FINISHED';}
  function togglePause(){if(!started)return;paused=!paused;$('pausePanel').style.display=paused?'block':'none';if(!paused)last=performance.now();}
  function frame(now){const dt=(now-last)/1000||0;last=now;update(dt);drawTrack();requestAnimationFrame(frame);}
  function beep(freq,duration,type='sine',volume=.03){if(!audio)return;const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.value=freq;g.gain.value=volume;o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+duration);}
  function updateEngineSound(){if(!audio)return;const now=audio.currentTime;if(!audio.engine){audio.engine=audio.createOscillator();audio.engine.type='sawtooth';audio.engineGain=audio.createGain();audio.engineGain.gain.value=.006;audio.engine.connect(audio.engineGain);audio.engineGain.connect(audio.destination);audio.engine.start();}audio.engine.frequency.setTargetAtTime(55+car.rpm/38,now,.04);audio.engineGain.gain.setTargetAtTime(.006+car.throttle*.018,now,.08);}
  $('startBtn').addEventListener('click',begin);
