  const elapsed = performance.now() - lightStart;
  const lit = Math.min(5, Math.floor(elapsed / 700));
  const cx = W / 2, cy = H * .305;
  const gap = clamp(W * .055, 42, 72), r = clamp(W * .0105, 7, 13);
  ctx.save();
  ctx.shadowColor = 'rgba(0,0,0,.65)'; ctx.shadowBlur = 30; ctx.shadowOffsetY = 10;
  ctx.fillStyle = 'rgba(6,10,15,.9)';
  ctx.beginPath(); ctx.roundRect(cx - gap * 3.15, cy - r * 3.1, gap * 6.3, r * 6.2, 10); ctx.fill();
  ctx.shadowBlur = 0; ctx.shadowOffsetY = 0;
  ctx.strokeStyle = 'rgba(255,255,255,.16)'; ctx.lineWidth = 1; ctx.stroke();
  for (let i = 0; i < 5; i++) {
    const x = cx + (i - 2) * gap;
    for (let row = 0; row < 2; row++) {
      const y = cy + (row ? r * 1.55 : -r * 1.55);
      ctx.fillStyle = '#15191c';
      ctx.beginPath(); ctx.arc(x, y, r, 0, Math.PI*2); ctx.fill();
      if (i < lit) {
        const glow = ctx.createRadialGradient(x, y, 1, x, y, r * 2.6);
