        ctx.fillStyle = glow; ctx.beginPath(); ctx.arc(x, y, r*2.6, 0, Math.PI*2); ctx.fill();
        ctx.fillStyle = '#ff3b2e'; ctx.beginPath(); ctx.arc(x, y, r*.8, 0, Math.PI*2); ctx.fill();
        ctx.fillStyle = 'rgba(255,220,210,.8)'; ctx.beginPath(); ctx.arc(x-r*.2, y-r*.2, r*.3, 0, Math.PI*2); ctx.fill();
