function ensureAudio() {
  if (!audio) {
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    audio = new AC();
  }
  if (audio.state === 'suspended') audio.resume();
}

function toggleSound() {
  soundOn = !soundOn;
  if (soundOn) {
    ensureAudio();
    if (!audio) { soundOn = false; return; }
    ensureEngineNodes();
    if (audio.engineGain) audio.engineGain.gain.setTargetAtTime(.01, audio.currentTime, .05);
    $('soundBtn').style.color = '#d8ff3e';
  } else {
    if (audio?.engineGain) audio.engineGain.gain.setTargetAtTime(0, audio.currentTime, .06);
    if (audio?.tyreGain) audio.tyreGain.gain.setTargetAtTime(0, audio.currentTime, .06);
    $('soundBtn').style.color = '';
  }
}
