const fs = require('fs');
const http = require('http');
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
function get(path) {
  return new Promise((resolve, reject) => {
    http.get('http://localhost:9222' + path, (res) => {
      let d = ''; res.on('data', (c) => d += c); res.on('end', () => resolve(JSON.parse(d)));
    }).on('error', reject);
  });
}
(async () => {
  const page = (await get('/json/list')).find((t) => t.type === 'page');
  const ws = new WebSocket(page.webSocketDebuggerUrl);
  let id = 0; const pending = new Map(); const errors = [];
  ws.onmessage = (ev) => {
    const m = JSON.parse(ev.data);
    if (m.id && pending.has(m.id)) {
      const p = pending.get(m.id); pending.delete(m.id);
      m.error ? p.reject(new Error(JSON.stringify(m.error))) : p.resolve(m.result);
    } else if (m.method === 'Runtime.exceptionThrown') errors.push(m.params);
  };
  await new Promise((r) => ws.onopen = r);
  const send = (method, params = {}) => new Promise((resolve, reject) => {
    const i = ++id; pending.set(i, { resolve, reject }); ws.send(JSON.stringify({ id: i, method, params }));
  });
  const ev = async (expression) => (await send('Runtime.evaluate', { expression, returnByValue: true })).result?.value;
  const shot = async (name) => {
    const r = await send('Page.captureScreenshot', { format: 'jpeg', quality: 84 });
    fs.writeFileSync(name, Buffer.from(r.data, 'base64'));
    console.log('shot', name);
  };
  await send('Page.enable');
  await send('Runtime.enable');
  await send('Emulation.setDeviceMetricsOverride', { width: 1280, height: 720, deviceScaleFactor: 1, mobile: false });
  await send('Page.navigate', { url: 'http://localhost:3002' });
  await sleep(2000);
  await shot('/tmp/opencode/v3-menu.jpg');
  await ev(`document.getElementById('startBtn').click()`);
  await sleep(1600);
  await shot('/tmp/opencode/v3-lights.jpg');
  await sleep(3300);
  console.log('phase', await ev('window.__APEX__.phase'), await ev('window.__APEX__.car.lateral'));
  await shot('/tmp/opencode/v3-grid.jpg');
  for (const [name, m] of [['c1', 900], ['c2', 1500], ['c3', 2400], ['c4', 3400], ['c5', 4300], ['c6', 5100], ['finishline', 5700]]) {
    await ev(`(()=>{const a=window.__APEX__;a.skip(${m});a.car.speed=76;a.car.rpm=11200;a.car.gear=7;a.car.grip=0.96;a.car.tyreTemp=98;})()`);
    await sleep(280);
    await shot('/tmp/opencode/v3-' + name + '.jpg');
