const fs = require('fs');
const http = require('http');
function get(path) {
  return new Promise((resolve, reject) => {
    http.get('http://localhost:9222' + path, (res) => {
      let d = ''; res.on('data', (c) => d += c); res.on('end', () => resolve(JSON.parse(d)));
    }).on('error', reject);
  });
}
(async () => {
  const page = (await get('/json/list')).find((t) => t.type === 'page');
  const ws = new WebSocket(page.webSocketDebuggerUrl);
  let id = 0; const pending = new Map();
  ws.onmessage = (ev) => {
    const m = JSON.parse(ev.data);
    if (m.id && pending.has(m.id)) {
      const p = pending.get(m.id); pending.delete(m.id);
      m.error ? p.reject(new Error(JSON.stringify(m.error))) : p.resolve(m.result);
    }
  };
  await new Promise((r) => ws.onopen = r);
  const send = (method, params = {}) => new Promise((resolve, reject) => {
    const i = ++id; pending.set(i, { resolve, reject }); ws.send(JSON.stringify({ id: i, method, params }));
  });
  const r = await send('Runtime.evaluate', {
    expression: `(()=>{const ids=['timer','statusText','lapTimes'];const o={};for(const id of ids){const e=document.getElementById(id);const b=e.getBoundingClientRect();o[id]={top:b.top,bottom:b.bottom,height:b.height,line:getComputedStyle(e).lineHeight,font:getComputedStyle(e).fontSize,mt:getComputedStyle(e).marginTop,display:getComputedStyle(e).display};}return o})()`,
    returnByValue: true
  });
  console.log(r.result.value);
  const shot = await send('Page.captureScreenshot', { format: 'png', clip: { x: 380, y: 80, width: 520, height: 110, scale: 2 } });
  fs.writeFileSync('/tmp/opencode/hud-crop.png', Buffer.from(shot.data, 'base64'));
  ws.close();
})().catch((e) => { console.error(e); process.exit(1); });

