const fs = require('fs');
const http = require('http');
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
function get(path) {
  return new Promise((resolve, reject) => {
    http.get('http://localhost:9222' + path, (res) => {
      let d = ''; res.on('data', (c) => d += c); res.on('end', () => resolve(JSON.parse(d)));
    }).on('error', reject);
  });
}
(async () => {
  const page = (await get('/json/list')).find((t) => t.type === 'page');
  const ws = new WebSocket(page.webSocketDebuggerUrl);
  let id = 0; const pending = new Map(); const errors = [];
  ws.onmessage = (ev) => {
    const m = JSON.parse(ev.data);
    if (m.id && pending.has(m.id)) {
      const p = pending.get(m.id); pending.delete(m.id);
      m.error ? p.reject(new Error(JSON.stringify(m.error))) : p.resolve(m.result);
    } else if (m.method === 'Runtime.exceptionThrown') errors.push(m.params);
  };
  await new Promise((r) => ws.onopen = r);
  const send = (method, params = {}) => new Promise((resolve, reject) => {
    const i = ++id; pending.set(i, { resolve, reject }); ws.send(JSON.stringify({ id: i, method, params }));
  });
  const ev = async (expression) => (await send('Runtime.evaluate', { expression, returnByValue: true })).result?.value;
  const shot = async (name) => {
    const r = await send('Page.captureScreenshot', { format: 'jpeg', quality: 82 });
    fs.writeFileSync(name, Buffer.from(r.data, 'base64'));
    console.log('shot', name);
  };
  await send('Page.enable');
  await send('Runtime.enable');
  await send('Emulation.setDeviceMetricsOverride', { width: 1280, height: 720, deviceScaleFactor: 1, mobile: false });
  await send('Page.navigate', { url: 'http://localhost:3002' });
  await sleep(1800);

  // sound + restart flow
  await ev(`document.getElementById('soundBtn').click()`);
  await sleep(300);
  console.log('sound btn', await ev(`document.getElementById('soundBtn').style.color`));
  await ev(`document.getElementById('startBtn').click()`);
  for (let i = 0; i < 80; i++) { if (await ev('window.__APEX__.phase') === 'racing') break; await sleep(120); }
  console.log('phase1', await ev('window.__APEX__.phase'));
  await ev(`window.__APEX__.finish()`);
  await sleep(400);
  console.log('result visible', await ev(`!document.getElementById('resultCard').classList.contains('hidden')`));
  await ev(`document.getElementById('restartBtn').click()`);
  await sleep(300);
  console.log('after restart', await ev(`({phase:window.__APEX__.phase,d:window.__APEX__.car.distance,startCard:document.getElementById('startCard').className,result:document.getElementById('resultCard').className})`));
  for (let i = 0; i < 80; i++) { if (await ev('window.__APEX__.phase') === 'racing') break; await sleep(120); }
  console.log('phase2', await ev('window.__APEX__.phase'), 'gridpos', await ev('window.__APEX__.car.lateral'));

  // mobile
  await send('Emulation.setDeviceMetricsOverride', { width: 390, height: 844, deviceScaleFactor: 1, mobile: true });
  await send('Page.navigate', { url: 'http://localhost:3002' });
  await sleep(1800);
  await shot('/tmp/opencode/m-menu.jpg');
  await ev(`document.getElementById('startBtn').click()`);
  await sleep(1500);
  await shot('/tmp/opencode/m-lights.jpg');
  for (let i = 0; i < 80; i++) { if (await ev('window.__APEX__.phase') === 'racing') break; await sleep(120); }
  await ev(`window.__APEX__.skip(1300); window.__APEX__.car.speed=72; window.__APEX__.car.gear=7; window.__APEX__.car.rpm=11000;`);
  await sleep(300);
  await shot('/tmp/opencode/m-race.jpg');
  await ev(`window.__APEX__.finish()`);
  await sleep(400);
  await shot('/tmp/opencode/m-result.jpg');
  console.log('errors', errors.length);
  ws.close();
})().catch((e) => { console.error(e); process.exit(1); });

content.text:
Now CSS existing `.mobile-controls` display none with justify-content: space-around. Add group styles and mobile media overrides. The existing media(max-width:700) has `.mobile-controls{display:flex}`. Append rules after:

```
.mobile-controls{justify-content:space-between;padding:0 10px}
.mobile-controls .mc-group{display:flex;gap:6px;pointer-events:auto}
@media(max-width:700px){
 .telemetry{display:none}
 .timer{font-size:19px!important}
 .mobile-controls{bottom:48px;padding:0 8px}
 .mobile-controls button{min-width:42px;height:44px;font-size:11px}
 .mobile-controls .gear-btn{min-width:40px;font-size:17px}
 ...
}
```
Note existing mobile media sets `.telemetry` transform, but display none overrides. Add at end of file so it wins.

Also hide controls on result via JS.

And `.mobile-controls` default display none; the appended `.mobile-controls{justify-content...}` doesn't change display. Good. The media display flex.

Add `.mc-group` pointer-events? The mobile-controls has pointer-events:none; buttons have pointer-events:auto; groups inherit none, but children auto works. Fine.

Result mobile: `.result-card` width; okay.

Now car y on mobile: in drawCar, `const baseY = W < 700 ? .80 : .855;` But W is viewport width; landscape phone with width 844 but height 390 would use .855, controls still shown? Media query width<700 would not show controls at 844 landscape? `@media(max-width:700px)` → landscape 844 doesn't show controls, so no need. However, mobile portrait width 390. Use H<600? Perhaps `W < 700` fine.

Also hide mobile controls on finish:
```
$('mobileControls').style.display='none'
```
in finishRace. begin sets display=''. On mobile, `display=''` → CSS flex; on desktop stays none. Good.

Also `togglePause` maybe leave controls visible; keys cleared.

Implement.

