function bendAt(distance) {
  const p = modulo(distance, TRACK) / TRACK;
  return .00034 * Math.sin(p * Math.PI * 2 * 2.15 + .35)
    + .00052 * Math.sin(p * Math.PI * 2 * 4.7 - .8)
    + .00033 * Math.sin(p * Math.PI * 2 * 8.3 + 1.2)
    + .0008 * Math.exp(-Math.pow((p - .20) / .025, 2))
    - .0010 * Math.exp(-Math.pow((p - .53) / .035, 2));
}

