const fs = require('fs');
const http = require('http');
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
function get(path) {
  return new Promise((resolve, reject) => {
    http.get('http://localhost:9222' + path, (res) => {
      let d = ''; res.on('data', (c) => d += c); res.on('end', () => resolve(JSON.parse(d)));
    }).on('error', reject);
  });
}
(async () => {
  const page = (await get('/json/list')).find((t) => t.type === 'page');
  const ws = new WebSocket(page.webSocketDebuggerUrl);
  let id = 0; const pending = new Map(); const errors = [];
  ws.onmessage = (ev) => {
    const m = JSON.parse(ev.data);
    if (m.id && pending.has(m.id)) {
      const p = pending.get(m.id); pending.delete(m.id);
      m.error ? p.reject(new Error(JSON.stringify(m.error))) : p.resolve(m.result);
    } else if (m.method === 'Runtime.exceptionThrown') errors.push(m.params);
  };
  await new Promise((r) => ws.onopen = r);
  const send = (method, params = {}) => new Promise((resolve, reject) => {
    const i = ++id; pending.set(i, { resolve, reject }); ws.send(JSON.stringify({ id: i, method, params }));
  });
  const ev = async (expression) => (await send('Runtime.evaluate', { expression, returnByValue: true })).result?.value;
  const key = (type, k, code, vk, text) => send('Input.dispatchKeyEvent', {
    type, key: k, code, windowsVirtualKeyCode: vk, nativeVirtualKeyCode: vk,
    text: type === 'keyDown' && text ? text : undefined
  });
  const held = new Set();
  async function setKey(k, code, vk, on, text) {
    if (on && !held.has(k)) { held.add(k); await key('keyDown', k, code, vk, text); }
    if (!on && held.has(k)) { held.delete(k); await key('keyUp', k, code, vk); }
  }
  async function shift(dir) {
    const k = dir > 0 ? 'e' : 'q';
    await key('keyDown', k, dir > 0 ? 'KeyE' : 'KeyQ', dir > 0 ? 69 : 81, k);
    await sleep(16);
    await key('keyUp', k, dir > 0 ? 'KeyE' : 'KeyQ', dir > 0 ? 69 : 81);
  }
  await send('Page.enable');
  await send('Runtime.enable');
  await send('Emulation.setDeviceMetricsOverride', { width: 1280, height: 720, deviceScaleFactor: 1, mobile: false });
  await send('Page.navigate', { url: 'http://localhost:3002' });
  await sleep(1600);
  await ev(`document.getElementById('startBtn').click()`);
  for (let i = 0; i < 100; i++) { if (await ev(`window.__APEX__.phase`) === 'racing') break; await sleep(120); }
  console.log('racing');
  await setKey('w', 'KeyW', 87, true, 'w');
  let lastLap = 1, offFrames = 0, frames = 0, maxSpeed = 0, lastGear = 1;
  const start = Date.now();
  while (Date.now() - start < 275000) {
    const st = await ev(`(()=>{const a=window.__APEX__,c=a.car;return {ph:a.phase,s:c.speed,lat:c.lateral,lv:c.latVel,rpm:c.rpm,gear:c.gear,off:c.offTrack,prog:c.progress,lap:c.lap,laps:c.lapTimes.length,best:c.best,d:c.distance,bend:a.bend(c.progress),bendAhead:Math.max(Math.abs(a.bend(c.progress+50)),Math.abs(a.bend(c.progress+110))),place:c.finalPlace,pos:document.getElementById('position').textContent}})()`);
    if (!st) break;
    frames++; maxSpeed = Math.max(maxSpeed, st.s);
    if (st.off) offFrames++;
    if (st.ph === 'finished') { console.log('FINISHED', JSON.stringify(st)); break; }
    if (st.lap !== lastLap) { console.log('LAP', st.lap, 'laps', JSON.stringify(st.laps), 'best', st.best, 't', ((Date.now() - start) / 1000).toFixed(1)); lastLap = st.lap; }
    const sev = Math.max(Math.abs(st.bend), st.bendAhead * .92);
    const target = 89 - 21 * Math.min(1, sev / .00135);
    const brake = st.s > target + 1.5;
    const throttle = !brake && st.s < target + 0.5;
    await setKey('s', 'KeyS', 83, brake, 's');
    await setKey('w', 'KeyW', 87, throttle, 'w');
    if (st.rpm > 12650 && st.gear < 8) { await shift(1); lastGear = st.gear + 1; }
    else if (st.rpm < 6800 && st.gear > 1) { await shift(-1); lastGear = st.gear - 1; }
    const steer = Math.max(-1, Math.min(1, -st.lat * 2.5 - st.lv * 1.1 + st.bend * 300));
    await setKey('d', 'KeyD', 68, steer > .16, 'd');
    await setKey('a', 'KeyA', 65, steer < -.16, 'a');
    await sleep(40);
  }
  await setKey('w', 'KeyW', 87, false);
  await setKey('s', 'KeyS', 83, false);
  await setKey('a', 'KeyA', 65, false);
  await setKey('d', 'KeyD', 68, false);
  await sleep(600);
  console.log('FINAL', JSON.stringify(await ev(`(()=>{const a=window.__APEX__,c=a.car;return {ph:a.phase,lap:c.lap,laps:c.lapTimes,best:c.best,wear:c.wear,top:c.topSpeed,dist:c.distance,place:c.finalPlace,pos:document.getElementById('position').textContent,resultTime:document.getElementById('resultTime').textContent,resultPos:document.getElementById('resultPos').textContent,resultBest:document.getElementById('resultBest').textContent,resultVisible:!document.getElementById('resultCard').classList.contains('hidden')}})()`)));
  console.log('offFrames', offFrames, '/', frames, 'maxSpeed', (maxSpeed * 3.6).toFixed(0), 'errors', errors.length);
  const r = await send('Page.captureScreenshot', { format: 'jpeg', quality: 84 });
  fs.writeFileSync('/tmp/opencode/race-end.jpg', Buffer.from(r.data, 'base64'));
